    (*state)[3][3] = (*state)[3][2];
    (*state)[3][2] = (*state)[3][1];
    (*state)[3][1] = (*state)[3][0];
    (*state)[3][0] = temp;
}

// xtime: multiply by 2 in GF(2^8)
static uint8_t xtime(uint8_t x) {
    return ((x << 1) ^ (((x >> 7) & 1) * 0x1b));
}

// MixColumns: mix the columns of the state
void MixColumns(state_t *state) {
    uint8_t i;
    uint8_t Tmp, Tm, t;
    for (i = 0; i < 4; i++) {
        t = (*state)[0][i];
        Tmp = (*state)[0][i] ^ (*state)[1][i] ^ (*state)[2][i] ^ (*state)[3][i];
        Tm = (*state)[0][i] ^ (*state)[1][i];
        Tm = xtime(Tm);
        (*state)[0][i] ^= Tm ^ Tmp;
        Tm = (*state)[1][i] ^ (*state)[2][i];
        Tm = xtime(Tm);
        (*state)[1][i] ^= Tm ^ Tmp;
        Tm = (*state)[2][i] ^ (*state)[3][i];
        Tm = xtime(Tm);
        (*state)[2][i] ^= Tm ^ Tmp;
        Tm = (*state)[3][i] ^ t;
        Tm = xtime(Tm);
        (*state)[3][i] ^= Tm ^ Tmp;
    }
}

// Cipher: main AES encryption function
void Cipher(state_t *state, const round_t *RoundKey) {
    uint8_t round;

    // Initial round
    AddRoundKey(0, state, RoundKey);

    // Main rounds
    for (round = 1; round < Nr; round++) {
        SubBytes(state);
        ShiftRows(state);
        MixColumns(state);
        AddRoundKey(round, state, RoundKey);
    }

    // Final round (no MixColumns)
    SubBytes(state);
    ShiftRows(state);
    AddRoundKey(Nr, state, RoundKey);
}
